-- https://lua.expert/
local t = {
	Name = "Spare Bulb",
	Icon = "rbxassetid://17653809409",
	Rarity = "Common",
	Description = "Increases Blackout light radius by 25%. Also increases light radius for light-producing Toons.",
	TrinketType = "Passive",
	MonsterTrinket = true,
	Cost = 350
}

t.Requirement1 = { "Coin", t.Cost }
function t.ApplyTrinket(p1) --[[ ApplyTrinket | Line: 17 ]]
	p1:WaitForChild("Trinkets")

	local Stats = p1:WaitForChild("Stats")

	Stats:WaitForChild("WalkSpeed")
	Stats:WaitForChild("RunSpeed")
	Stats:WaitForChild("SpeedModifier")
	p1:WaitForChild("Humanoid")
	Stats:WaitForChild("Sprinting")

	local HumanoidRootPart = p1:WaitForChild("HumanoidRootPart")

	if not HumanoidRootPart:FindFirstChild("ToonLight") then
		return
	end

	local PointLight = HumanoidRootPart:WaitForChild("ToonLight").PointLight

	PointLight.Range = PointLight.Range * 1.25
end
function t.RemoveTrinket(p1) --[[ RemoveTrinket | Line: 33 ]]
	local Trinkets = p1:WaitForChild("Trinkets")
	local HumanoidRootPart = p1:FindFirstChild("HumanoidRootPart")
	local Trinket1 = Trinkets:FindFirstChild("Trinket1")
	local Trinket2 = Trinkets:FindFirstChild("Trinket2")

	if not (Trinket1 and Trinket2) then
		return "CantRemove"
	end

	if Trinket1.Value == script.Name then
		Trinket1.Value = "None"

		if not (HumanoidRootPart and HumanoidRootPart:FindFirstChild("ToonLight")) then
			return "Slot1"
		end

		local PointLight = HumanoidRootPart.ToonLight.PointLight

		PointLight.Range = PointLight.Range / 1.25

		return "Slot1"
	end

	if Trinket2.Value ~= script.Name then
		return "CantRemove"
	end

	Trinket2.Value = "None"

	if not (HumanoidRootPart and HumanoidRootPart:FindFirstChild("ToonLight")) then
		return "Slot2"
	end

	local PointLight = HumanoidRootPart.ToonLight.PointLight

	PointLight.Range = PointLight.Range / 1.25

	return "Slot2"
end

return t